using UnityEngine;
using XCharts.Runtime;

public class Update
{
    public static void Execute(BaseChart chart, string element_id, float value)
    {
        Debug.Log("Executing Update logic...");

        int serieIndex = 0;
        int dataIndex = 0;

        if (element_id.Contains(":"))
        {
            string[] parts = element_id.Split(':');
            int.TryParse(parts[0], out serieIndex);
            int.TryParse(parts[1], out dataIndex);
        }
        else
        {
            int.TryParse(element_id, out dataIndex);
        }

        var serie = chart.GetSerie(serieIndex);
        if (serie == null)
        {
            Debug.LogWarning($"Update: Serie {serieIndex} not found.");
            return;
        }

        if (dataIndex < 0 || dataIndex >= serie.dataCount)
        {
            Debug.LogWarning($"Update: DataIndex {dataIndex} out of range for serie {serieIndex} (count={serie.dataCount}).");
            return;
        }

        chart.UpdateData(serieIndex, dataIndex, (double)value);
        chart.RefreshChart();
    }
}

using UnityEngine;
