using System.Collections.Generic;

public class DeleteElement
{
    public static void Execute(BaseChart chart, string element_id)
    {
        Debug.Log("Executing DeleteElement logic...");

        int serieIndex = 0;
        int dataIndex = 0;

        if (element_id.Contains(":"))
        {
            string[] parts = element_id.Split(':');
            int.TryParse(parts[0], out serieIndex);
            int.TryParse(parts[1], out dataIndex);
        }
        else
        {
            int.TryParse(element_id, out dataIndex);
        }

        var serie = chart.GetSerie(serieIndex);
        if (serie == null)
        {
            Debug.LogWarning($"DeleteElement: Serie {serieIndex} not found.");
            return;
        }

        if (dataIndex < 0 || dataIndex >= serie.dataCount)
        {
            Debug.LogWarning($"DeleteElement: DataIndex {dataIndex} out of range.");
            return;
        }

        serie.RemoveData(dataIndex);

        var xAxis = chart.GetChartComponent<XAxis>();
        if (xAxis != null && xAxis.IsCategory() && dataIndex < xAxis.data.Count)
        {
            xAxis.RemoveData(dataIndex);
        }

        chart.RefreshChart();
    }
}

using UnityEngine;
using XCharts.Runtime;

public class Append
{
    public static void Execute(BaseChart chart, float value, int serieIndex = 0, string dataName = null)
    {
        Debug.Log("Executing Append logic...");

        var serie = chart.GetSerie(serieIndex);
        if (serie == null)
        {
            Debug.LogWarning($"Append: Serie {serieIndex} not found.");
            return;
        }

        var xAxis = chart.GetChartComponent<XAxis>();
        if (xAxis != null && xAxis.IsCategory())
        {
            string label = dataName ?? ("x" + (xAxis.GetAddedDataCount() + 1));
            chart.AddXAxisData(label);
        }

        chart.AddData(serieIndex, (double)value, dataName);
        chart.RefreshChart();
    }
}

using UnityEngine;
using XCharts.Runtime;

public class Highlight
{
    /// <summary>
    /// highlight_type: "select" | "emphasis" | "blur" | "none"
    /// </summary>
    public static void Execute(BaseChart chart, string element_id, string highlight_type)
    {
        Debug.Log("Executing Highlight logic...");

        int serieIndex = 0;
        int dataIndex = 0;

        if (element_id.Contains(":"))
        {
            string[] parts = element_id.Split(':');
            int.TryParse(parts[0], out serieIndex);
            int.TryParse(parts[1], out dataIndex);
        }
        else
        {
            int.TryParse(element_id, out dataIndex);
        }

        var serie = chart.GetSerie(serieIndex);
        if (serie == null)
        {
            Debug.LogWarning($"Highlight: Serie {serieIndex} not found.");
            return;
        }

        if (dataIndex < 0 || dataIndex >= serie.dataCount)
        {
            Debug.LogWarning($"Highlight: DataIndex {dataIndex} out of range.");
            return;
        }

        switch (highlight_type.ToLower())
        {
            case "select":
                var sd = serie.GetSerieData(dataIndex);
                if (sd != null) sd.selected = true;
                break;

            case "emphasis":
                if (serie.emphasisStyle == null)
                {
                    Debug.LogWarning("Highlight: serie.emphasisStyle is null. Creating new instance — may lack Inspector defaults.");
                    serie.emphasisStyle = new EmphasisStyle();
                }
                serie.emphasisStyle.focus = EmphasisStyle.FocusType.Self;
                var sdEmphasis = serie.GetSerieData(dataIndex);
                if (sdEmphasis != null) sdEmphasis.selected = true;
                break;

            case "blur":
                if (serie.emphasisStyle == null)
                {
                    Debug.LogWarning("Highlight: serie.emphasisStyle is null. Creating new instance — may lack Inspector defaults.");
                    serie.emphasisStyle = new EmphasisStyle();
                }
                serie.emphasisStyle.blurScope = EmphasisStyle.BlurScope.Global;
                // Also select the target element so blur takes visible effect on others
                var sdBlur = serie.GetSerieData(dataIndex);
                if (sdBlur != null) sdBlur.selected = true;
                break;

            case "none":
                for (int i = 0; i < serie.dataCount; i++)
                {
                    var data = serie.GetSerieData(i);
                    if (data != null) data.selected = false;
                }
                break;

            default:
                Debug.LogWarning($"Highlight: Unknown highlight_type '{highlight_type}'. Use: select, emphasis, blur, none.");
                break;
        }

        chart.RefreshChart();
    }
}
